using System;using System.IO;using System.ComponentModel;using System.ServiceProcess;using System.Security.Principal;using Microsoft.Win32;
internal static class LenovoDriverBootstrap {
 internal static string ExpectedPath{get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),@"Lenovo\Lenovo Diagnostics Evolution\LenovoDiagnosticsDriver.sys");}}
 internal static void EnsureRunning(){LenovoOemTransport.Verify();using(var key=Registry.LocalMachine.OpenSubKey(@"SYSTEM\CurrentControlSet\Services\LenovoDiagnosticsDriver")){if(key==null)throw new IOException("Pilote Lenovo Diagnostics non installé");string path=Environment.ExpandEnvironmentVariables(Convert.ToString(key.GetValue("ImagePath"))).Trim('"');if(path.StartsWith(@"\??\"))path=path.Substring(4);if(!String.Equals(Path.GetFullPath(path),Path.GetFullPath(ExpectedPath),StringComparison.OrdinalIgnoreCase)||Convert.ToInt32(key.GetValue("Type"))!=1)throw new IOException("Service du pilote Lenovo différent de la version vérifiée");if(Convert.ToInt32(key.GetValue("Start"))==4)throw new IOException("Le pilote Lenovo est désactivé dans Windows");}using(var driver=new ServiceController("LenovoDiagnosticsDriver")){if(driver.Status==ServiceControllerStatus.Running)return;if(driver.Status==ServiceControllerStatus.StopPending)driver.WaitForStatus(ServiceControllerStatus.Stopped,TimeSpan.FromSeconds(8));if(driver.Status!=ServiceControllerStatus.StartPending){try{driver.Start();}catch(InvalidOperationException){driver.Refresh();if(driver.Status!=ServiceControllerStatus.Running&&driver.Status!=ServiceControllerStatus.StartPending)throw;}}driver.WaitForStatus(ServiceControllerStatus.Running,TimeSpan.FromSeconds(8));}}
}
